# Register the INTERACTIVE daily popup (daily.ps1) as a Windows scheduled task.
# It opens a real terminal window on trading days (EGX trades Sun-Thu, 10:00-
# 14:30). Fires at 10:00, market open, so you can act during the session. The
# suggestion it shows was generated by the headless job the evening before
# (after the 14:30 close), i.e. it is based on the latest available close.
# /IT = interactive: it only fires when you are logged on, popping a window.
#
# Run once (from the project root), in a normal PowerShell:
#     powershell -ExecutionPolicy Bypass -File ops\register_daily_popup.ps1
# Remove it with:
#     schtasks /Delete /TN "ESIS-QUANT Daily Popup" /F

$ErrorActionPreference = "Stop"
$root   = Split-Path -Parent $PSScriptRoot          # project root (parent of ops\)
$script = Join-Path $root "daily.ps1"
$run    = "powershell -NoExit -ExecutionPolicy Bypass -File `"$script`""

schtasks /Create `
  /TN "ESIS-QUANT Daily Popup" `
  /TR $run `
  /SC WEEKLY `
  /D SUN,MON,TUE,WED,THU `
  /ST 10:00 `
  /IT `
  /F

# schtasks can't set these, so patch them via the ScheduledTasks module.
#   StartWhenAvailable: if the PC was off/asleep at 10:00, run as soon as it is
#     back. Without this a missed morning is silently skipped until the next day.
#   The two Batteries flags: schtasks defaults BOTH to true, which on a laptop
#     means the task refuses to start on battery AND is KILLED mid-run if the
#     charger comes out. That is what actually happened -- the 2026-08-13 17:00
#     run died with 0xC000013A (terminated) after writing nothing but ^C to
#     logs\daily_run.log, and the daily report then went stale for six days.
#   Restart*: one transient failure should not cost a whole session.
$t = Get-ScheduledTask -TaskName "ESIS-QUANT Daily Popup"
$t.Settings.StartWhenAvailable         = $true
$t.Settings.DisallowStartIfOnBatteries = $false
$t.Settings.StopIfGoingOnBatteries     = $false
$t.Settings.RestartCount               = 2
$t.Settings.RestartInterval            = "PT10M"
Set-ScheduledTask -TaskName "ESIS-QUANT Daily Popup" -Settings $t.Settings | Out-Null

Write-Host ""
Write-Host "Registered 'ESIS-QUANT Daily Popup' -> Sun-Thu 10:00 (market open), pops daily.ps1." -ForegroundColor Green
Write-Host "Missed-start catch-up ON: if the PC is off at 10:00 it pops at next power-on." -ForegroundColor Green
Write-Host "Test it now with:  schtasks /Run /TN `"ESIS-QUANT Daily Popup`"" -ForegroundColor Gray
